#!/usr/bin/env python3
"""Turn 35 Wave 38: MATCHCRAFT layer - C-spam defence escalation ladder, anti-wing/anti-C backwards-running, close-control touch fix, free-kick goal-line trick, secondary-press model, counter-attack recipe, long-B meta, auto-switch off, formation meta, Training facility full ladder, gem-heal conversion table, Commercial-scam conflict."""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w38')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid
def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid
os.makedirs(RAW_DIR,exist_ok=True)

# ---------- EV-436: matchcraft ----------
e_mc=new_ev("r/DreamLeagueSoccer 1rx01zi (Mar 2026 Tips/Tricks List), 16n9is4 (Sep 2023 How I play DLL in Tier 1), 1ivjcvs (Feb 2025 tier-1 4-1-3-2 guide), 1i6kf6d (Jan 2025 strategies), 1qbzi64 (Jan 2026 how to defend in DLL), 179q1fa (Oct 2023), psaaqtm (Sep 2021 auto-switch), 1plnrjw (Dec 2025 meta formation), ktwxpz, dlsmod.com How to Win DLS Online Matches, LevelWinner formations guide",
    "MATCHCRAFT - THE TIER-1 SKILL LAYER. (1) B-DEFENCE RULE: when defending and holding B, do NOT use the joystick - your player always moves toward the ball automatically. (2) ANTI-WING SPAM: do not try to tackle the outermost players as the opponent switches the ball, because that leaves your players stranded upfield. Instead switch to defensive mode and RUN YOUR PLAYERS BACKWARDS at every opportunity, concentrating your team in your own third so crosses and diagonal box passes become easy to defend. (3) ANTI-C SPAM: the same backwards-running principle applied with central midfielders - you will intercept the lofted passes quickly; on intercept, switch to attacking mode and counter. (4) CLOSE-CONTROL TOUCH FIX: dribbling at pace and then switching direction often produces an extra unwanted touch in the original direction. Just BEFORE switching direction, HOLD THE SCREEN for close control - this stops the extra touch and makes the change of direction clean. Release immediately afterwards to resume normal dribbling. (5) FREE-KICK DEFENCE: there is not enough time to press A for a defensive header, so move a player onto the GOAL LINE before the kick; that player gets auto-switched to quickly, and using the 'trick shot' DOUBLE-TAP control produces an immediate header and goal-line clearance. (6) C-SPAM DEFENCE ESCALATION LADDER (the highest-value single finding): when two strikers run at you, head the ball diagonally - backwards AND slightly in the same direction as the second striker. If they still C-spam, escalate the formation: 3 at the back -> 4 -> 5. If they still C-spam and your formation had three vertical lines (4-4-2, 5-3-2), switch to one with four or five vertical lines such as 4-1-2-1-2 or 5-2-1-2. This is reported to negate 95% of C-spamming. (7) A-SPAM DEFENCE (crossing side to side then cutting back to a striker in the box): switch to 4-1-2-1-2 DEFENSIVE, because once they reach the crossing stage only poor composure stops them - the key is cutting them off earlier. (8) SECONDARY PRESS MODEL: do not always use the main press button (B); use the SECONDARY press so a teammate applies pressure while you position your player to block the pass or shot. The same applies to aerial duels - against C-spammers avoid holding the main press and use the secondary press while covering the goal. (9) AUTO-SWITCH OFF is the recommended setting against C-spam, practised first in Career Mode. (10) COUNTER-ATTACK RECIPE: 3 attackers up front, fast wingers (Salah right, Vinicius or Dembele left) and a clinical striker (Haaland/Kane/Mbappe/Lewandowski). Win the ball, kick to the free winger, sprint, and if a defender comes, hold C or A and pass to the OPPOSITE winger who is always free in a counterattack; then shoot or lob over the centre-backs and press A in the 1v1. (11) C-SPAM OFFENSIVE: tall, fast forwards with the C button at a power bar slightly over half beats the defensive line for a 1v1. (12) LONG B PASS META: diagonal grounded B passes to wingers, best when you dispossess the opponent in your own half - press the Heatmap button and switch to ATTACKING mode before pressing and holding B. (13) GENERAL DEFENSIVE RULES: never push forward with your defenders; use a DM to press in midfield; play zonal defending out of possession; slide-tackle sparingly because of yellow-card risk; block shots; press C to bring the keeper out; and switch tactics frequently - go DEFENSIVE when you cannot reach the ball in your own half (so midfielders and forwards track back and create 2v1s), then switch to ATTACKING on winning possession to push wingers forward and play long balls with less than a full power bar. (14) POSSESSION MODEL for tier 1: hold the ball and build slowly - 'when you have it, your opponent can't score' - using short accurate midfield passes and practising in the Corner training mode. (15) NO BLIND PASSES OR SHOTS: no blind C passes, no blind shots, dribble while stopped, call out the keeper when necessary. (16) LONG SHOTS have more than 75% accuracy in DLS with the correct power and player. (17) FORMATION META is unsettled: 4-4-2 is advocated for balance (LM/RM as wingers, full-backs supporting both phases), while the tier-1 guides favour 4-1-2-1-2 and 4-1-3-2, and sportsdunia pushes 4-3-3 and 3-4-1-2.",
    "evidence/raw/turn35_w38/EV-436_matchcraft.html",
    "MATCHCRAFT: hold B while defending and DO NOT touch the joystick (auto-moves to the ball); ANTI-WING and ANTI-C SPAM = run players BACKWARDS into your own third rather than tackling the outermost player; close-control touch fix = hold the screen just before switching direction to kill the extra touch; free-kick defence = put a player on the goal line and double-tap for a trick-shot header; C-SPAM ESCALATION LADDER = head diagonally backwards-and-across, then 3->4->5 at the back, then switch from 3 vertical lines to 4-5 lines (4-1-2-1-2 / 5-2-1-2) - negates 95% of C-spam; A-spam defence = 4-1-2-1-2 DEFENSIVE; SECONDARY PRESS beats the main press for both tackles and aerial duels; turn AUTO-SWITCH OFF (practise in Career first); counter-attack recipe with 3 up top and the free opposite winger; C-spam offence at just over half power; long-B diagonal grounded pass meta after pressing the Heatmap button and switching to ATTACKING; never push defenders forward, use a DM, zonal defending, block shots, press C for the keeper, switch tactics frequently; tier-1 possession model = hold the ball, short passes, Corner training mode; no blind C passes or blind shots; long shots >75% accuracy; formation meta unsettled (4-4-2 vs 4-1-2-1-2/4-1-3-2 vs 4-3-3/3-4-1-2)",
    quality="community")

